/* IMU data structure */

typedef struct imu_data
{
  float accel_x;
  float accel_y;
  float accel_z;
  float gyro_x;
  float gyro_y;
  float gyro_z;
  uint32_t timestamp;
} imu_data_t;

/* Three-stage fall detector state. */

typedef enum fall_stage
{
  FALL_STAGE_NONE = 0,
  FALL_STAGE_FREEFALL,
  FALL_STAGE_IMPACT,
  FALL_STAGE_STILL
} fall_stage_t;

typedef struct fall_detector
{
  fall_stage_t stage;
  uint32_t stage_start_ms;
  bool confirmed;
} fall_detector_t;

/* Motion detection state */

typedef struct motion_state
{
  bool is_moving;
  bool is_running;
  bool fall_detected;
  float motion_intensity;
  uint32_t last_motion_time;
  uint32_t motion_count;
} motion_state_t;

/* IMU sensor structure */

typedef struct imu_sensor
{
  int fd;
  bool initialized;
  imu_data_t buffer[IMU_BUFFER_SIZE];
  int buffer_index;
  motion_state_t motion;
  fall_detector_t fall_detector;
  float threshold_move;
  float threshold_run;
  float threshold_fall;
} imu_sensor_t;

