/****************************************************************************
 * Public Functions
 ****************************************************************************/

int event_manager_dispatch(velawear_events_t *events,
                           velawear_event_t *event)
{
  event_handler_entry_t handlers[EVENT_HANDLER_MAX];
  int handler_count;

  if (events == NULL || event == NULL)
    {
      return VELAWEAR_ERR_INVAL;
    }

  /* Snapshot registrations before invoking callbacks.  Handlers are
   * external code and may register another handler; never hold the manager
   * lock across that call. */
  pthread_mutex_lock(&events->lock);
  handler_count = events->handler_count;
  memcpy(handlers, events->handlers,
         handler_count * sizeof(event_handler_entry_t));
  pthread_mutex_unlock(&events->lock);

  for (int i = 0; i < handler_count; i++)
    {
      int ret;

      if (handlers[i].event_type == event->type ||
          handlers[i].event_type == VELAWEAR_EVENT_NONE)
        {
          ret = handlers[i].handler(event, handlers[i].context);
          if (ret < 0)
            {
              syslog(LOG_WARNING,
                     "[EventMgr] Handler %d returned error: %d\n",
                     i, ret);
            }
        }
    }

  return VELAWEAR_OK;
}


int event_manager_init(velawear_events_t *events)
{
  struct mq_attr attr;
  int ret;

  if (events == NULL)
    {
      return VELAWEAR_ERR_INVAL;
    }

  memset(events, 0, sizeof(velawear_events_t));
  events->queue = (mqd_t)-1;

  /* Initialize mutex */

  ret = pthread_mutex_init(&events->lock, NULL);
  if (ret != 0)
    {
      return VELAWEAR_ERR_IO;
    }

  /* Create message queue */

  attr.mq_flags = 0;
  attr.mq_maxmsg = EVENT_QUEUE_SIZE;
  /* Keep the mqueue payload within CONFIG_MQ_MAXMSGSIZE.  Events are
   * copied through heap-backed pointers so the full event union can
   * remain available to handlers. */
  attr.mq_msgsize = sizeof(uintptr_t);
  attr.mq_curmsgs = 0;

  /* A crashed instance may leave pointer messages behind.  Remove the
   * old queue before creating a fresh one for this process. */
  mq_unlink("/velawear_events");

  events->queue = mq_open("/velawear_events", O_CREAT | O_RDWR, 0644,
                          &attr);
  if (events->queue == (mqd_t)-1)
    {
      syslog(LOG_ERR, "[EventMgr] Failed to create message queue: %d\n",
             errno);
      return VELAWEAR_ERR_IO;
    }

  events->running = false;
  events->handler_count = 0;

  syslog(LOG_INFO, "[EventMgr] Initialized\n");
  return VELAWEAR_OK;
}

int event_manager_start(velawear_events_t *events)
{
  int ret;

  if (events->running)
    {
      return VELAWEAR_ERR_BUSY;
    }

  events->running = true;

  ret = pthread_create(&events->thread, NULL, event_manager_thread, events);
  if (ret != 0)
    {
      syslog(LOG_ERR, "[EventMgr] Failed to create thread: %d\n", ret);
      events->running = false;
      return VELAWEAR_ERR_IO;
    }

  syslog(LOG_INFO, "[EventMgr] Started\n");
/*
 * VelaWear Agent - Action Manager Implementation
 *
 * Manages all actions: display, vibrate, BLE, LLM, etc.
 *
 * Author: pjjuihj
 * Team: 329 - dela
 */

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <syslog.h>
#include <pthread.h>
#include <unistd.h>

#include "velawear.h"
#include "action_manager.h"

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void *action_manager_thread(void *arg)
{
  velawear_actions_t *actions = (velawear_actions_t *)arg;
  velawear_action_t action;
  int ret;

  syslog(LOG_INFO, "[ActionMgr] Thread started\n");

  while (actions->running)
    {
      /* Wait for action in queue */

      pthread_mutex_lock(&actions->lock);

      while (actions->queue_count == 0 && actions->running)
        {
          pthread_cond_wait(&actions->cond, &actions->lock);
        }

      if (!actions->running)
        {
          pthread_mutex_unlock(&actions->lock);
          break;
        }

      /* Dequeue action */

      memcpy(&action, &actions->queue[actions->queue_head],
             sizeof(velawear_action_t));
      actions->queue_head =
        (actions->queue_head + 1) % ACTION_QUEUE_SIZE;
      actions->queue_count--;

      pthread_mutex_unlock(&actions->lock);

      /* Dispatch action to handler */

      for (int i = 0; i < actions->handler_count; i++)
        {
          if (actions->handlers[i].action_type == action.type)
            {
              ret = actions->handlers[i].handler(&action,
                                                 actions->handlers[i].context);
              if (ret < 0)
                {
                  syslog(LOG_WARNING,
                         "[ActionMgr] Handler for type %d failed: %d\n",
                         action.type, ret);
                }
              break;
            }
        }
    }

  syslog(LOG_INFO, "[ActionMgr] Thread stopped\n");
  return NULL;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int action_manager_init(velawear_actions_t *actions)
{
  memset(actions, 0, sizeof(velawear_actions_t));

  pthread_mutex_init(&actions->lock, NULL);
  pthread_cond_init(&actions->cond, NULL);

  actions->running = false;
  actions->queue_head = 0;
  actions->queue_tail = 0;
  actions->queue_count = 0;

  syslog(LOG_INFO, "[ActionMgr] Initialized\n");
  return VELAWEAR_OK;
}

int action_manager_start(velawear_actions_t *actions)
{
  int ret;

  if (actions->running)
    {
      return VELAWEAR_ERR_BUSY;
    }

  actions->running = true;

  ret = pthread_create(&actions->thread, NULL, action_manager_thread, actions);
  if (ret != 0)
    {
      syslog(LOG_ERR, "[ActionMgr] Failed to create thread: %d\n", ret);
      actions->running = false;
      return VELAWEAR_ERR_IO;
    }

  syslog(LOG_INFO, "[ActionMgr] Started\n");
  return VELAWEAR_OK;
}

