function b64(s) {
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  let out = "";
  for (let i = 0; i < s.length; i += 3) {
    const a = s.charCodeAt(i);
    const hasB = i + 1 < s.length;
    const hasC = i + 2 < s.length;
    const b = hasB ? s.charCodeAt(i + 1) : 0;
    const c = hasC ? s.charCodeAt(i + 2) : 0;
    out += chars[(a >> 2) & 63];
    out += chars[((a & 3) << 4) | ((b >> 4) & 15)];
    out += hasB ? chars[((b & 15) << 2) | ((c >> 6) & 3)] : "=";
    out += hasC ? chars[c & 63] : "=";
  }
  return out;
}
