static void velawear_signal_handler(int signo);
static void *velawear_imu_thread(void *context);
static void *velawear_watchdog_thread(void *context);
static int velawear_watchdog_start_software(velawear_agent_t *agent);
static int velawear_watchdog_start(velawear_agent_t *agent);
static void velawear_watchdog_stop(velawear_agent_t *agent);
static void velawear_watchdog_ping(velawear_agent_t *agent);
static void velawear_set_degradation_mode(velawear_agent_t *agent,
                                             int mode,
                                             const char *reason);
static int velawear_retry_imu(velawear_agent_t *agent);
static int velawear_retry_audio(velawear_agent_t *agent);
static void velawear_set_power_mode(velawear_agent_t *agent,
                                    int mode,
                                    const char *reason);
static int velawear_event_handler(velawear_event_t *event, void *context);
static int velawear_log_action_handler(velawear_action_t *action,
                                       void *context);
static int velawear_vibrate_action_handler(velawear_action_t *action,
                                            void *context);
static int velawear_show_ui_action_handler(velawear_action_t *action,
                                            void *context);
static int velawear_send_ble_action_handler(velawear_action_t *action,
                                             void *context);

static int velawear_dump_framebuffer(bool center)
{
  static const char alphabet[] =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  struct fb_videoinfo_s vinfo;
  struct fb_planeinfo_s pinfo;
  FAR uint8_t *pixels;
  char encoded[4];
  char output[1024];
  size_t offset;
  size_t encoded_len;
  size_t output_len = 0;
  size_t line_len = 0;
  size_t row;
  size_t row_bytes;
  size_t x0 = 0;
  size_t y0;
  size_t width;
  size_t height;
  size_t frame_bytes;
  size_t bytes_per_pixel;
  size_t i;
  int fd;
  int ret;

  fd = open("/dev/fb0", O_RDWR);
  if (fd < 0)
    {
      printf("[LCDDUMP] open /dev/fb0 failed: %d\n", errno);
      return -errno;
    }

  memset(&vinfo, 0, sizeof(vinfo));
  memset(&pinfo, 0, sizeof(pinfo));
  pinfo.display = 0;
  ret = ioctl(fd, FBIOGET_VIDEOINFO,
              (unsigned long)((uintptr_t)&vinfo));
  if (ret < 0)
    {
      printf("[LCDDUMP] FBIOGET_VIDEOINFO failed: %d\n", errno);
      close(fd);
      return -errno;
    }

  ret = ioctl(fd, FBIOGET_PLANEINFO,
              (unsigned long)((uintptr_t)&pinfo));
  if (ret < 0)
    {
      printf("[LCDDUMP] FBIOGET_PLANEINFO failed: %d\n", errno);
      close(fd);
      return -errno;
    }

  pixels = mmap(NULL, pinfo.fblen, PROT_READ, MAP_SHARED | MAP_FILE, fd, 0);
  if (pixels == MAP_FAILED)
    {
      printf("[LCDDUMP] mmap failed: %d\n", errno);
      close(fd);
      return -errno;
    }

  bytes_per_pixel = pinfo.bpp / 8;
  y0 = center ? 180 : 0;
  width = vinfo.xres;
  height = center ? 100 : vinfo.yres - y0;
  if (y0 >= vinfo.yres || bytes_per_pixel == 0)
    {
      munmap(pixels, pinfo.fblen);
      close(fd);
      return -EINVAL;
    }

  if (height > vinfo.yres - y0)
    {
      height = vinfo.yres - y0;
    }

  row_bytes = width * bytes_per_pixel;
  frame_bytes = row_bytes * height;
  printf("LCDDUMP_BEGIN %u %u %u %u %zu\n",
         (unsigned int)width, (unsigned int)height,
         (unsigned int)pinfo.bpp, (unsigned int)pinfo.stride, frame_bytes);

