static int velawear_write_all(const char *buffer, size_t length)
{
  while (length > 0)
    {
      size_t request = length > 64 ? 64 : length;
      ssize_t written = write(STDOUT_FILENO, buffer, request);

      if (written > 0)
        {
          buffer += written;
          length -= written;
          usleep(10000);
        }
      else if (written < 0 && (errno == EINTR || errno == EAGAIN))
        {
          usleep(1000);
        }
      else
        {
          return -1;
        }
    }

  return 0;
}

static int velawear_dump_lcd_capture(void)
{
  static const char alphabet[] =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  const size_t width = 390;
  const size_t height = 100;
  const size_t frame_bytes = width * height * 2;
  uint8_t *snapshot;
  char encoded[4];
  char output[1024];
  size_t offset;
  size_t encoded_len;
  size_t output_len = 0;
  size_t line_len = 0;
  size_t i;
  int ret;

  snapshot = malloc(frame_bytes);
  if (snapshot == NULL)
    {
      return -ENOMEM;
    }

  ret = sf32lb_lcd_copy_capture(snapshot, frame_bytes);
  if (ret < 0)
    {
      printf("[LCDSHADOW] capture unavailable: %d\n", ret);
      free(snapshot);
      return ret;
    }

  printf("LCDSHADOW_BEGIN %u %u %u %u %zu\n",
         (unsigned int)width, (unsigned int)height, 16U,
         (unsigned int)(width * 2), frame_bytes);

  for (offset = 0; offset < frame_bytes; offset += 3)
    {
      size_t remaining = frame_bytes - offset;
      uint32_t a = snapshot[offset];
      uint32_t b = remaining > 1 ? snapshot[offset + 1] : 0;
      uint32_t c = remaining > 2 ? snapshot[offset + 2] : 0;

      encoded_len = 0;
      encoded[encoded_len++] = alphabet[(a >> 2) & 0x3f];
      encoded[encoded_len++] = alphabet[((a & 0x03) << 4) |
                                        ((b >> 4) & 0x0f)];
      encoded[encoded_len++] = remaining > 1 ?
        alphabet[((b & 0x0f) << 2) | ((c >> 6) & 0x03)] : '=';
      encoded[encoded_len++] = remaining > 2 ? alphabet[c & 0x3f] : '=';

      for (i = 0; i < encoded_len; i++)
        {
          output[output_len++] = encoded[i];
          line_len++;
          if (line_len == 72)
            {
              output[output_len++] = '\n';
              line_len = 0;
            }

          if (output_len >= sizeof(output) - 4)
            {
              if (velawear_write_all(output, output_len) < 0)
                {
                  free(snapshot);
                  return -EIO;
                }

              output_len = 0;
            }
        }
    }

  if (line_len != 0)
    {
      output[output_len++] = '\n';
    }
  if (output_len != 0 && velawear_write_all(output, output_len) < 0)
    {
      free(snapshot);
      return -EIO;
    }

  printf("LCDSHADOW_END\n");
  free(snapshot);
  return 0;
}

static int velawear_dump_framebuffer(bool center)
{
  static const char alphabet[] =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  struct fb_videoinfo_s vinfo;
  struct fb_planeinfo_s pinfo;
  FAR uint8_t *pixels;
  FAR uint8_t *snapshot;
  char encoded[4];
  char output[1024];
  size_t offset;
  size_t encoded_len;
  size_t output_len = 0;
  size_t line_len = 0;
  size_t row;
  size_t row_bytes;
  size_t x0 = 0;
  size_t y0;
  size_t width;
  size_t height;
  size_t frame_bytes;
  size_t bytes_per_pixel;
  size_t i;
  int fd;
  int ret;

  fd = open("/dev/fb0", O_RDWR);
  if (fd < 0)
    {
      printf("[LCDDUMP] open /dev/fb0 failed: %d\n", errno);
      return -errno;
    }

  memset(&vinfo, 0, sizeof(vinfo));
  memset(&pinfo, 0, sizeof(pinfo));
  pinfo.display = 0;
  ret = ioctl(fd, FBIOGET_VIDEOINFO,
              (unsigned long)((uintptr_t)&vinfo));
  if (ret < 0)
    {
      printf("[LCDDUMP] FBIOGET_VIDEOINFO failed: %d\n", errno);
      close(fd);
      return -errno;
    }

  ret = ioctl(fd, FBIOGET_PLANEINFO,
              (unsigned long)((uintptr_t)&pinfo));
  if (ret < 0)
    {
      printf("[LCDDUMP] FBIOGET_PLANEINFO failed: %d\n", errno);
      close(fd);
      return -errno;
    }

  pixels = mmap(NULL, pinfo.fblen, PROT_READ, MAP_SHARED | MAP_FILE, fd, 0);
  if (pixels == MAP_FAILED)
    {
      printf("[LCDDUMP] mmap failed: %d\n", errno);
      close(fd);
      return -errno;
    }

  bytes_per_pixel = pinfo.bpp / 8;
  y0 = center ? 180 : 0;
  width = vinfo.xres;
  height = center ? 100 : vinfo.yres - y0;
  if (y0 >= vinfo.yres || bytes_per_pixel == 0)
    {
      munmap(pixels, pinfo.fblen);
      close(fd);
      return -EINVAL;
    }

