356: int main(int argc, char *argv[])
357: {
358:   int ret;
359:   bool falltest = argc > 1 && strcmp(argv[1], "falltest") == 0;
360: 
361:   if (argc > 1 && strcmp(argv[1], "dumpfb") == 0)
362:     {
363:       return velawear_dump_framebuffer(argc > 2 &&
364:                                        strcmp(argv[2], "center") == 0);
365:     }
366: 
367:   if (argc > 1 && strcmp(argv[1], "dumpshadow") == 0)
368:     {
369:       return velawear_dump_lcd_capture();
370:     }
371: 
372:   if (argc > 1 && strcmp(argv[1], "audio") == 0)
373:     {
374:       return velawear_audio_hw_test();
375:     }
376: 
377:   if (argc > 1 && strcmp(argv[1], "beep") == 0)
378:     {
379:       return velawear_speaker_alert(500, 0);
380:     }
381: 
382:   if (argc > 1 && strcmp(argv[1], "music") == 0)
383:     {
384:       return velawear_music_hw_test();
385:     }
386: 
387:   syslog(LOG_INFO, "[VelaWear] Agent starting...\n");
388:   if (argc > 1 && strcmp(argv[1], "mic") == 0)
389:     {
390:       return velawear_mic_hw_test();
391:     }
392: 
393:   /* Initialize agent structure */
394: 
395:   memset(&g_agent, 0, sizeof(velawear_agent_t));
396:   g_agent.running = false;
397:   g_agent.watchdog_fd = -1;
398:   g_agent.power_mode = VELAWEAR_POWER_IDLE;
399:   g_agent.operation_mode = VELAWEAR_MODE_ONLINE;
400:   g_agent.imu_available = false;
401:   g_agent.audio_available = false;
402:   g_agent.ble_available = false;
403: 
404:   /* Set up signal handler */
405: 
406:   signal(SIGTERM, velawear_signal_handler);
407:   signal(SIGINT, velawear_signal_handler);
408: 
409:   /* Initialize subsystems */
410: 
411:   ret = velawear_init(&g_agent);
412:   if (ret < 0)
413:     {
414:       syslog(LOG_ERR, "[VelaWear] Initialization failed: %d\n", ret);
415:       return EXIT_FAILURE;
416:     }
417: 
418:   /* Start the agent */
419: 
420:   ret = velawear_start(&g_agent);
421:   if (ret < 0)
422:     {
423:       syslog(LOG_ERR, "[VelaWear] Start failed: %d\n", ret);
424:       velawear_cleanup(&g_agent);
425:       return EXIT_FAILURE;
426:     }
427: 
428:   syslog(LOG_INFO, "[VelaWear] Agent started successfully\n");
429: 
430:   /* Main event loop: block waiting for events.  IMU sampling runs in its
431:    * producer thread so this task remains the single queue consumer. */
432:   {
433:     bool falltest_sent = false;
434:     uint32_t last_activity_ms = velawear_now_ms();
435: 
436:     while (g_agent.running)
437:       {
438:         velawear_event_t event;
439:         int event_ret;
440:         int wait_ms;
441: 
442:         if (g_agent.power_mode == VELAWEAR_POWER_DEEP_SLEEP)
443:           {
444:             wait_ms = 100;
445:           }
446:         else if (g_agent.power_mode == VELAWEAR_POWER_LIGHT_SLEEP)
447:           {
448:             wait_ms = 100;
449:           }
450:         else if (g_agent.power_mode == VELAWEAR_POWER_IDLE)
451:           {
452:             wait_ms = 100;
453:           }
454:         else
455:           {
456:             wait_ms = 100;
457:           }
458: 
459:         if (falltest && !falltest_sent)
460:           {
461:             memset(&event, 0, sizeof(event));
462:             event.type = VELAWEAR_EVENT_FALL;
463:             event.priority = VELAWEAR_PRIORITY_CRITICAL;
464:             if (event_manager_push(&g_agent.events, &event) < 0)
465:               {
466:                 syslog(LOG_ERR,
467:                        "[VelaWear] Fall self-test event enqueue failed\n");
468:               }
469:             else
470:               {
471:                 syslog(LOG_INFO,
472:                        "[VelaWear] Fall self-test event queued\n");
473:               }
474:             falltest_sent = true;
475:           }
476: 
477:         event_ret = event_manager_pop(&g_agent.events, &event, wait_ms);
478:         if (event_ret == VELAWEAR_OK)
479:           {
480:             if (event.type != VELAWEAR_EVENT_MOTION)
481:               {
482:                 last_activity_ms = velawear_now_ms();
483:                 velawear_set_power_mode(&g_agent, VELAWEAR_POWER_ACTIVE,
484:                                         "event received");
485:               }
486:             event_ret = event_manager_dispatch(&g_agent.events, &event);
487:             if (event_ret < 0)
488:               {
489:                 syslog(LOG_WARNING,
490:                        "[VelaWear] Event dispatch failed: %d\n", event_ret);
491:               }
492:             else if (falltest && event.type == VELAWEAR_EVENT_FALL)
493:               {
494:                 /* Give action worker and main-thread display handoff time to run. */
495:                 for (int i = 0; i < 10; i++)
496:                   {
497:                     usleep(100000);
498:                     display_manager_tick(&g_agent.display);
499:                   }
500:                 g_agent.running = false;
501:               }
502:           }
