static int velawear_ble_read_status(FAR struct bt_conn_s *conn,
                                    FAR const struct bt_gatt_attr_s *attr,
                                    FAR void *buf, uint8_t len,
                                    uint16_t offset)
{
  uint8_t value[3];

  (void)attr;
  pthread_mutex_lock(&g_lock);
  value[0] = (uint8_t)g_motion_type;
  value[1] = g_intensity_percent;
  value[2] = g_alert_active ? 1 : 0;
  pthread_mutex_unlock(&g_lock);

  return bt_gatt_attr_read(conn, attr, buf, len, offset,
                           value, sizeof(value));
}

static int velawear_ble_read_threshold(FAR struct bt_conn_s *conn,
                                       FAR const struct bt_gatt_attr_s *attr,
                                       FAR void *buf, uint8_t len,
                                       uint16_t offset)
{
  uint16_t seconds;

  (void)attr;
  pthread_mutex_lock(&g_lock);
  seconds = (uint16_t)g_config->sedentary_threshold_sec;
  pthread_mutex_unlock(&g_lock);

  return bt_gatt_attr_read(conn, attr, buf, len, offset,
                           &seconds, sizeof(seconds));
}

static int velawear_ble_write_threshold(FAR struct bt_conn_s *conn,
                                        FAR const struct bt_gatt_attr_s *attr,
                                        FAR const void *buf, uint8_t len,
                                        uint16_t offset)
{
  const uint8_t *data = (const uint8_t *)buf;
  uint16_t seconds;

  (void)conn;
  (void)attr;
  if (buf == NULL || offset != 0 || len != sizeof(uint16_t))
    {
      return -EINVAL;
    }

  seconds = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
  if (seconds < 10 || seconds > 3600)
    {
      return -EINVAL;
    }

  pthread_mutex_lock(&g_lock);
  g_config->sedentary_threshold_sec = seconds;
  pthread_mutex_unlock(&g_lock);
  syslog(LOG_INFO, "[BLE] Sedentary threshold updated: %u s\n",
         (unsigned int)seconds);
  return len;
}

