  q_cfg.tx_buf_addr = SF32LB52_BT_TX_BUF_ADDR;
  q_cfg.tx_buf_addr_alias = SF32LB52_BT_TX_BUF_ALIAS;
  q_cfg.rx_buf_addr = SF32LB52_BT_RX_BUF_ADDR;
