  if (g_sf32lb52_bt_status == SF32LB52_BT_STATUS_IDLE)
    {
      return -EPERM;
    }

  g_sf32lb52_bt_env.notify_host = callback;
  return OK;
}

int sf32lb52_bt_controller_enable(void)
{
  int ret;

  if (g_sf32lb52_bt_status == SF32LB52_BT_STATUS_ENABLED)
    {
      return OK;
    }

  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_INITED)
    {
      return -EPERM;
    }

  sf32lb52_bt_prepare_stack_nvds();
  HAL_LCPU_ASSERT_INFO_clear();

  ret = lcpu_power_on();
  if (ret != 0)
    {
      return -EIO;
    }

  /* The L2H_MAILBOX (0x40002000) is on the LPSYS APB bus.  Its CxIER
   * register is only writable when the LPSYS bus bridge is active.
   * Wake the LCPU first so the bus bridge is powered, THEN open the
   * IPC queue (which writes CxIER to unmask the mailbox RX interrupt).
   * The SDK reference ipc_hw_enable_interrupt2() has the same
   * HAL_HPAON_WakeCore() before the UNMASK call.
   */

  HAL_HPAON_WakeCore(CORE_ID_LCPU);
  g_sf32lb52_bt_env.wake_held = true;

  usleep(500000);

  ret = ipc_queue_open(g_sf32lb52_bt_env.ipc_port);
  if (ret < 0)
    {
      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
      g_sf32lb52_bt_env.wake_held = false;
      return ret;
    }

  /* Flush H2L TX ring to SRAM immediately after ipc_queue_open so
   * LCPU sees the reset indices (read_idx=write_idx=0) before it
   * tries to process any stale data from a previous session.
   */
  up_clean_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
                  (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
                  SF32LB52_BT_TX_BUF_SIZE);
  __DSB();

  /* After every lcpu_power_on(), LCPU resets its TX ring write pointer
   * (write_idx_mirror) to 0 and writes its own boot responses into the
   * ring.  HCPU's read pointer (read_idx_mirror) may still hold the
   * non-zero value from the previous session -- dirty in DCache or
   * stored in SRAM.  If we do not synchronise them:
   *
   *   circular_buf_data_len() = wrap(write_idx - read_idx)
   *
   * returns a large garbage value, and LCPU's fresh boot events
   * plus ring garbage all replay as "new" HCI responses.  These
   * ghost events are consumed by the host as replies to real commands,
   * so HCI_Reset (0x0c01) is never actually executed by the controller,
   * and bt_le_adv_start later gets "Command Disallowed" (0x07).
   *
   * Fix: flush DCache to write back any dirty read_idx and to load
   * LCPU's current write_idx from SRAM, then advance read_idx to
   * write_idx (discard ALL pending LCPU boot data), then clean the
   * DCache so LCPU sees the updated read pointer in SRAM.
   */

  {
    struct circular_buf *rx_ring =
        (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;

    ret = sf32lb52_bt_wait_rx_ring_ready();
    if (ret < 0)
      {
        syslog(LOG_ERR, "sf32lb52 rx ring not ready: %d\n", ret);
        ipc_queue_close(g_sf32lb52_bt_env.ipc_port);
        HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
        g_sf32lb52_bt_env.wake_held = false;
        return ret;
      }

    rx_ring->read_idx_mirror = rx_ring->write_idx_mirror;
    g_sf32lb52_bt_env.rx_read_idx_mirror = rx_ring->write_idx_mirror;

    up_clean_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
                    (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
                    sizeof(*rx_ring));
    __DSB();
  }

  {
    volatile MAILBOX_CH_TypeDef *l2h = L2H_MAILBOX;
    uint32_t nvic_bit = (1UL << (LCPU2HCPU_IRQn & 0x1F));
    uint32_t nvic_en  = NVIC->ISER[LCPU2HCPU_IRQn >> 5];

    (void)l2h;
    (void)nvic_bit;
    (void)nvic_en;
  }

  g_sf32lb52_bt_env.queue_open = true;
  g_sf32lb52_bt_status = SF32LB52_BT_STATUS_ENABLED;

  return OK;
}

int sf32lb52_bt_controller_disable(void)
{
  int ret = OK;
  int tmpret;
  bool queue_open;

  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_ENABLED)
    {
      return -EPERM;
    }

  queue_open = g_sf32lb52_bt_env.queue_open;
  g_sf32lb52_bt_env.queue_open = false;
  g_sf32lb52_bt_env.rx_work_pending = false;
  g_sf32lb52_bt_env.rx_worker_running = false;
  if (!work_available(&g_sf32lb52_bt_env.rx_work))
    {
      tmpret = work_cancel_sync(HPWORK, &g_sf32lb52_bt_env.rx_work);
      if (tmpret < 0 && tmpret != -ENOENT && ret == OK)
        {
          ret = tmpret;
        }
    }

  if (queue_open)
    {
      tmpret = ipc_queue_close(g_sf32lb52_bt_env.ipc_port);
      if (tmpret < 0 && ret == OK)
        {
          ret = tmpret;
        }
    }

  if (g_sf32lb52_bt_env.wake_held)
    {
      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
      g_sf32lb52_bt_env.wake_held = false;
    }

  tmpret = lcpu_power_off();
  if (tmpret != 0 && ret == OK)
    {
      ret = -EIO;
    }

  g_sf32lb52_bt_env.notify_host = NULL;
  g_sf32lb52_bt_status = SF32LB52_BT_STATUS_INITED;
  return ret;
}

int sf32lb52_host_send_packet(const uint8_t *data, uint16_t len)
{
  struct circular_buf *tx_ring =
      (struct circular_buf *)SF32LB52_BT_TX_BUF_ADDR;
  uint32_t start_time;
  uint32_t tick_count;
  size_t written;
  size_t remaining;
  size_t offset;
  size_t chunk;
  size_t chunks;
  uint32_t wr_ptr;
  int ret;

  if (data == NULL || len == 0)
    {
      return -EINVAL;
    }

  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_ENABLED ||
      !g_sf32lb52_bt_env.queue_open)
    {
      return -ENODEV;
    }

  offset = 0;
  remaining = len;
  start_time = HAL_GetTick();
  tick_count = 0;
  chunks = 0;
  wr_ptr = 0;

  ret = sf32lb52_bt_wait_tx_idle(tx_ring);
  if (ret < 0)
    {
      return ret;
    }

  while (remaining > 0)
    {
      irqstate_t flags;

      chunk = sf32lb52_bt_tx_chunk_len(data, len, offset);

      up_invalidate_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
                           (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
                           sizeof(*tx_ring));

      flags = enter_critical_section();
      written = sf32lb52_bt_ring_write(tx_ring, data + offset, chunk);
      leave_critical_section(flags);

      if (written == 0)
        {
          if (HAL_GetTick() != start_time)
            {
              tick_count++;
              start_time = HAL_GetTick();
            }

          if (tick_count >= 10)
            {
              syslog(LOG_ERR,
                     "sf32lb52 bt tx timeout: remaining=%lu\n",
                     (unsigned long)remaining);
              return -ETIMEDOUT;
            }

          continue;
        }

      offset += written;
      remaining -= written;

      __DSB();
      wr_ptr = tx_ring->write_idx_mirror;
      sf32lb52_bt_trigger_tx();
      chunks++;
    }

#if SF32LB52_BT_TRACE
  syslog(LOG_INFO,
         "sf32lb52 bt tx publish: total=%u chunks=%lu wr=%08lx first=%02x\n",
         len,
         (unsigned long)chunks,
         (unsigned long)wr_ptr,
         data[0]);

  sf32lb52_bt_log_tx_state(tx_ring, "queued", wr_ptr);
#endif

  if (data[0] == SF32LB52_BT_H4_CMD)
    {
      ret = sf32lb52_bt_wait_tx_idle(tx_ring);
      if (ret < 0)
        {
          return ret;
        }
    }

  return OK;
}

  switch (data[0])
    {
      case H4_EVT:
        sf32lb52_bt_normalize_event(data, len);
        type = BT_EVT;
        break;

      case H4_ACL:
        type = BT_ACL_IN;
        break;

      case H4_ISO:
        type = BT_ISO_IN;
        break;

      default:
        return -EINVAL;
    }

  ret = bt_netdev_receive(&priv->drv,
                          type,
                          (void *)&data[H4_HEADER_SIZE],
                          len - H4_HEADER_SIZE);
  if (ret < 0)
    {
      wlerr("Failed to receive HCI packet: %d\n", ret);
    }

  return ret;
}

static int sf32lb52_bt_synth_cmd_complete(struct sf32lb52_bt_priv_s *priv,
                                          uint16_t opcode,
                                          const uint8_t *return_params,
                                          size_t return_len)
{
  uint8_t event[H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + 3 +
                SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN];
  size_t payload_len;

  if (return_len > SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN)
    {
      return -E2BIG;
    }

  payload_len = 3 + return_len;
  event[0] = H4_EVT;
  event[1] = BT_HCI_EVT_CMD_COMPLETE;
  event[2] = payload_len;
  event[3] = 1;
  sf32lb52_bt_put_le16(&event[4], opcode);
  if (return_len > 0)
    {
      memcpy(&event[6], return_params, return_len);
    }

  return sf32lb52_bt_forward_packet(priv, event,
                                    H4_HEADER_SIZE +
                                    sizeof(struct bt_hci_evt_hdr_s) +
                                    payload_len);
}

static int sf32lb52_bt_synth_status_complete(struct sf32lb52_bt_priv_s *priv,
                                             uint16_t opcode)
{
  const uint8_t status = SF32LB52_HCI_STATUS_SUCCESS;

  return sf32lb52_bt_synth_cmd_complete(priv, opcode, &status,
                                        sizeof(status));
}

static bool sf32lb52_bt_emulate_cmd(struct sf32lb52_bt_priv_s *priv,
                                    uint16_t opcode, int *ret)
{
  uint8_t params[SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN];

  switch (opcode)
    {
      case BT_HCI_OP_READ_SUPPORTED_COMMANDS:
        memset(params, 0, sizeof(params));
        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
        params[1 + 27] = 1 << 7;
        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params,
                                              SF32LB52_HCI_READ_COMMANDS_RPLEN);
        return true;

      case BT_HCI_OP_LE_RAND:
        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
        arc4random_buf(&params[1], SF32LB52_HCI_RAND_RPLEN - 1);
        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params,
                                              SF32LB52_HCI_RAND_RPLEN);
        return true;

      case BT_HCI_OP_READ_LOCAL_EXT_FEATURES:
        memset(params, 0, 11);
        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 11);
        return true;

      case BT_HCI_OP_READ_BUFFER_SIZE:
        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
        sf32lb52_bt_put_le16(&params[1], 0x00fb);
        params[3] = 0;
        sf32lb52_bt_put_le16(&params[4], 4);
        sf32lb52_bt_put_le16(&params[6], 0);
        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 8);
        return true;

      case BT_HCI_OP_LE_READ_BUFFER_SIZE:
        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
        sf32lb52_bt_put_le16(&params[1], 0x00fb);
        params[3] = 4;
        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 4);
        return true;

      case BT_HCI_OP_LE_READ_LOCAL_FEATURES:
        memset(params, 0, 9);
        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 9);
        return true;

      case BT_HCI_OP_LE_READ_MAX_DATA_LEN:
        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
        sf32lb52_bt_put_le16(&params[1], 0x00fb);
        sf32lb52_bt_put_le16(&params[3], 0x0148);
        sf32lb52_bt_put_le16(&params[5], 0x00fb);
        sf32lb52_bt_put_le16(&params[7], 0x0148);
        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 9);
        return true;

      case BT_HCI_OP_LE_READ_MAX_ADV_DATA_LEN:
        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
        sf32lb52_bt_put_le16(&params[1], 31);
        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 3);
        return true;

      case BT_HCI_OP_LE_READ_SUPP_STATES:
        memset(params, 0, 9);
        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 9);
        return true;

      case BT_HCI_OP_LE_READ_RL_SIZE:
        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
        params[1] = 0;
        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 2);
        return true;

      case BT_HCI_OP_LE_WRITE_LE_HOST_SUPP:
      case BT_HCI_OP_LE_SET_HOST_FEATURE:
      case BT_HCI_OP_LE_SET_EVENT_MASK:
      case BT_HCI_OP_LE_WRITE_DEFAULT_DATA_LEN:
      case BT_HCI_OP_LE_SET_RPA_TIMEOUT:
      case BT_HCI_OP_SET_EVENT_MASK:
      case BT_HCI_OP_SET_EVENT_MASK_PAGE_2:
      case BT_HCI_OP_WRITE_LOCAL_NAME:
      case BT_HCI_OP_WRITE_SCAN_ENABLE:
      case BT_HCI_OP_WRITE_PAGE_SCAN_ACTIVITY:
      case BT_HCI_OP_WRITE_INQUIRY_SCAN_ACTIVITY:
      case BT_HCI_OP_WRITE_PAGE_TIMEOUT:
      case BT_HCI_OP_WRITE_CLASS_OF_DEVICE:
      case BT_HCI_OP_WRITE_INQUIRY_SCAN_TYPE:
      case BT_HCI_OP_WRITE_EXTENDED_INQUIRY_RESPONSE:
      case BT_HCI_OP_WRITE_INQUIRY_MODE:
      case BT_HCI_OP_WRITE_PAGE_SCAN_TYPE:
      case BT_HCI_OP_WRITE_SSP_MODE:
      case BT_HCI_OP_WRITE_SC_HOST_SUPP:
      case BT_HCI_OP_WRITE_DEFAULT_LINK_POLICY_SETTINGS:
      case BT_HCI_OP_HOST_BUFFER_SIZE:
      case BT_HCI_OP_SET_CTL_TO_HOST_FLOW:
        *ret = sf32lb52_bt_synth_status_complete(priv, opcode);
        return true;

      default:
        return false;
    }
}

static struct sf32lb52_bt_priv_s g_sf32lb52_bt_priv =
{
  .drv =
    {
      .head_reserve = H4_HEADER_SIZE,
      .open         = sf32lb52_bt_open,
      .send         = sf32lb52_bt_send,
      .close        = sf32lb52_bt_close,
    },
};

static int sf32lb52_bt_recv_cb(uint8_t *data, uint16_t len)
{
  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
  ssize_t packet_len;
  int ret;

  if (data == NULL || len == 0)
    {
      return -EINVAL;
    }

  if (priv->drop_rx_until_tx)
    {
      return OK;
    }

  if (priv->rxlen + len > sizeof(priv->rxbuf))
    {
      syslog(LOG_ERR,
             "sf32lb52 bth4 rx overflow: pending=%lu incoming=%u\n",
             (unsigned long)priv->rxlen,
             len);
      priv->rxlen = 0;
    }

  memcpy(&priv->rxbuf[priv->rxlen], data, len);
  priv->rxlen += len;

#if SF32LB52_BT_TRACE
  syslog(LOG_INFO,
         "sf32lb52 bth4 recv: len=%u pending=%lu first=%02x\n",
         len, (unsigned long)priv->rxlen, priv->rxbuf[0]);
#endif

  ret = OK;

  while (priv->rxlen > 0)
    {
      packet_len = sf32lb52_bt_h4_packet_len(priv->rxbuf, priv->rxlen);
      if (packet_len == 0)
        {
          break;
        }

      if (packet_len < 0)
        {
          syslog(LOG_WARNING,
                 "sf32lb52 bth4 drop invalid h4 type=%02x pending=%lu\n",
                 priv->rxbuf[0],
                 (unsigned long)priv->rxlen);
          memmove(priv->rxbuf, &priv->rxbuf[1], priv->rxlen - 1);
          priv->rxlen--;
          ret = -EINVAL;
          continue;
        }

      if ((size_t)packet_len > priv->rxlen)
        {
          break;
        }

      ret = sf32lb52_bt_forward_packet(priv, priv->rxbuf,
                   (size_t)packet_len);

      priv->rxlen -= (size_t)packet_len;
      if (priv->rxlen > 0)
        {
          memmove(priv->rxbuf,
                  &priv->rxbuf[packet_len],
                  priv->rxlen);
        }
    }

  return ret;
}

static int sf32lb52_bt_send(struct bt_driver_s *drv,
                            enum bt_buf_type_e type,
                            void *data, size_t len)
{
  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
  uint8_t *hdr = (uint8_t *)data - drv->head_reserve;
  uint16_t opcode;
  int ret;

  switch (type)
    {
      case BT_CMD:
        *hdr = H4_CMD;
        break;
      case BT_ACL_OUT:
        *hdr = H4_ACL;
        break;
      case BT_ISO_OUT:
        *hdr = H4_ISO;
        break;
      default:
        return -EINVAL;
    }

  if (type == BT_CMD && len >= sizeof(struct bt_hci_cmd_hdr_s))
    {
      opcode = sf32lb52_bt_get_le16(data);
      if (sf32lb52_bt_emulate_cmd(priv, opcode, &ret))
        {
          return ret < 0 ? ret : len;
        }

      ret = sf32lb52_bt_ensure_controller_enabled(opcode);
      if (ret < 0)
        {
          return ret;
        }
    }
  else
    {
      ret = sf32lb52_bt_ensure_controller_enabled(0);
      if (ret < 0)
        {
          return ret;
        }
    }

  priv->drop_rx_until_tx = false;

  if (SF32LB52_BT_TRACE && type == BT_ACL_OUT)
    {
      syslog(LOG_INFO,
             "sf32lb52 bth4 tx: type=%u len=%lu h4=%02x acl=%02x %02x %02x %02x\n",
             (unsigned int)type,
             (unsigned long)(len + drv->head_reserve),
             hdr[0],
             len >= 1 ? hdr[1] : 0,
             len >= 2 ? hdr[2] : 0,
             len >= 3 ? hdr[3] : 0,
             len >= 4 ? hdr[4] : 0);
    }

  ret = sf32lb52_host_send_packet(hdr, len + drv->head_reserve);
  if (ret < 0)
    {
      return ret;
    }

  return len;
}

static int sf32lb52_bt_ensure_controller_enabled(uint16_t opcode)
{
  int ret;

  ret = sf32lb52_bt_controller_enable();
  if (ret < 0)
    {
      syslog(LOG_ERR,
             "sf32lb52 bth4 controller enable failed before opcode=0x%04x: %d\n",
             opcode,
             ret);
    }

  return ret;
}

static int sf32lb52_bt_open(struct bt_driver_s *drv)
{
  int ret;

  (void)drv;

  g_sf32lb52_bt_priv.rxlen = 0;
  g_sf32lb52_bt_priv.drop_rx_until_tx = true;

  ret = sf32lb52_bt_controller_init();
  if (ret < 0)
    {
      return ret;
    }

  ret = sf32lb52_hci_register_callback(sf32lb52_bt_recv_cb);
  if (ret < 0)
    {
      return ret;
    }

  return OK;
}

static void sf32lb52_bt_close(struct bt_driver_s *drv)
{
  int ret;

  (void)drv;

  g_sf32lb52_bt_priv.rxlen = 0;

  /* Full deinit (not just disable) so that the next open re-initialises
   * the IPC queue from a clean state.  Without deinit, controller_init
   * is skipped on re-open (status != IDLE), and LCPU's ring-buffer
   * read pointer (reset on power-on) diverges from HCPU's stale write
   * pointer, causing all HCI commands to be silently dropped. */
  ret = sf32lb52_bt_controller_deinit();
  if (ret < 0)
    {
      wlerr("Failed to deinit HCI controller: %d\n", ret);
    }
}

int sf32lb52_bt_initialize(void)
{
  int ret;

  ret = uart_bth4_register("/dev/ttyHCI0", &g_sf32lb52_bt_priv.drv);
  if (ret < 0 && ret != -EEXIST)
    {
      wlerr("Failed to register /dev/ttyHCI0: %d\n", ret);
      return ret;
    }

  sf32lb52_bt_zblue_init_once();

  return OK;
}

static void le_read_buffer_size_complete(struct bt_dev *hdev, struct net_buf *buf)
{
	struct bt_hci_rp_le_read_buffer_size *rp = (void *)buf->data;

	LOG_DBG("status 0x%02x %s", rp->status, bt_hci_err_to_str(rp->status));

#if defined(CONFIG_BT_CONN)
	uint16_t acl_mtu = sys_le16_to_cpu(rp->le_max_len);

	if (!acl_mtu || !rp->le_max_num) {
		return;
	}

	hdev->le.acl_mtu = acl_mtu;

	LOG_DBG("ACL LE buffers: pkts %u mtu %u", rp->le_max_num, hdev->le.acl_mtu);

	k_sem_init(&hdev->le.acl_pkts, rp->le_max_num, rp->le_max_num);
#endif /* CONFIG_BT_CONN */
}

static void read_buffer_size_v2_complete(struct bt_dev *hdev, struct net_buf *buf)
{
#if defined(CONFIG_BT_ISO)
	struct bt_hci_rp_le_read_buffer_size_v2 *rp = (void *)buf->data;

	LOG_DBG("status %u %s", rp->status, bt_hci_err_to_str(rp->status));

#if defined(CONFIG_BT_CONN)
	uint16_t acl_mtu = sys_le16_to_cpu(rp->acl_max_len);

	if (acl_mtu && rp->acl_max_num) {
		hdev->le.acl_mtu = acl_mtu;
		LOG_DBG("ACL LE buffers: pkts %u mtu %u", rp->acl_max_num, hdev->le.acl_mtu);

		k_sem_init(&hdev->le.acl_pkts, rp->acl_max_num, rp->acl_max_num);
	}
#endif /* CONFIG_BT_CONN */

	uint16_t iso_mtu = sys_le16_to_cpu(rp->iso_max_len);

	if (!iso_mtu || !rp->iso_max_num) {
		LOG_ERR("ISO buffer size not set");
		return;
	}

	hdev->le.iso_mtu = iso_mtu;

	LOG_DBG("ISO buffers: pkts %u mtu %u", rp->iso_max_num, hdev->le.iso_mtu);

	k_sem_init(&hdev->le.iso_pkts, rp->iso_max_num, rp->iso_max_num);
	hdev->le.iso_limit = rp->iso_max_num;
#endif /* CONFIG_BT_ISO */
}

static int le_set_host_feature(struct bt_dev *hdev, uint8_t bit_number, uint8_t bit_value)
{
	struct bt_hci_cp_le_set_host_feature *cp;
	struct net_buf *buf;

	buf = bt_hci_cmd_create(BT_HCI_OP_LE_SET_HOST_FEATURE, sizeof(*cp));
	if (!buf) {
		return -ENOBUFS;
	}

	cp = net_buf_add(buf, sizeof(*cp));
	cp->bit_number = bit_number;
	cp->bit_value = bit_value;

	return bt_hci_cmd_send_sync(hdev, BT_HCI_OP_LE_SET_HOST_FEATURE, buf, NULL);
}

