void bt_finalize_init(struct bt_dev *hdev)
{
	atomic_set_bit(hdev->flags, BT_DEV_READY);

	if (IS_ENABLED(CONFIG_BT_OBSERVER)) {
		bt_scan_reset(hdev);
	}

	bt_dev_show_info(hdev);
}

static int bt_init(struct bt_dev *hdev)
{
	int err;

	err = hci_init(hdev);
	if (err) {
		return err;
	}

	if (IS_ENABLED(CONFIG_BT_CONN)) {
		err = bt_conn_init(hdev);
		if (err) {
			return err;
		}
	}

	if (IS_ENABLED(CONFIG_BT_ISO)) {
		err = bt_conn_iso_init(hdev);
		if (err) {
			return err;
		}
	}

	if (IS_ENABLED(CONFIG_BT_SETTINGS)) {
		if (!hdev->id_count) {
			LOG_INF("No ID address. App must call settings_load()");
			return 0;
		}

		atomic_set_bit(hdev->flags, BT_DEV_PRESET_ID);
	}

	bt_finalize_init(hdev);
	return 0;
}

static void init_work(struct k_work *work)
{
	int err;
	struct bt_dev *hdev = CONTAINER_OF(work, struct bt_dev, init);

	err = bt_init(hdev);
	if (hdev->ready_cb) {
		hdev->ready_cb(hdev->dev_id, err);
	}
}

static void rx_work_handler(struct k_work *work)
{
	int err;
	struct net_buf *buf;
	struct bt_dev *hdev = CONTAINER_OF(work, struct bt_dev, rx_work);

	LOG_DBG("dev:%d, Getting net_buf from queue", hdev->dev_id);
	buf = net_buf_slist_get(&hdev->rx_queue);
	if (!buf) {
		return;
	}

	LOG_DBG("buf %p type %u len %u", buf, bt_buf_get_type(buf), buf->len);

	switch (bt_buf_get_type(buf)) {
#if defined(CONFIG_BT_CONN)
	case BT_BUF_ACL_IN:
		hci_acl(hdev, buf);
		break;
#endif /* CONFIG_BT_CONN */
#if defined(CONFIG_BT_ISO)
	case BT_BUF_ISO_IN:
		hci_iso(hdev, buf);
		break;
#endif /* CONFIG_BT_ISO */
	case BT_BUF_EVT:
		hci_event(hdev, buf);
		break;
	default:
		LOG_ERR("Unknown buf type %u", bt_buf_get_type(buf));
		net_buf_unref(buf);
		break;
	}

	/* Schedule the work handler to be executed again if there are
	 * additional items in the queue. This allows for other users of the
	 * work queue to get a chance at running, which wouldn't be possible if
	 * we used a while() loop with a k_yield() statement.
	 */
	if (!sys_slist_is_empty(&hdev->rx_queue)) {

#if defined(CONFIG_BT_RECV_WORKQ_SYS)
		err = k_work_submit(&hdev->rx_work);
#elif defined(CONFIG_BT_RECV_WORKQ_BT)
		err = k_work_submit_to_queue(&bt_workq, &hdev->rx_work);
#endif
		if (err < 0) {
			LOG_ERR("Could not submit rx_work: %d", err);
		}
	}
}

