struct cmd_data {
	/* Extend the bt_buf user data */
	struct bt_buf_data buf_data;

	/** HCI status of the command completion */
	uint8_t  status;

	/** The command OpCode that the buffer contains */
	uint16_t opcode;

	/** The state to update when command completes with success. */
	struct bt_hci_cmd_state_set *state;

	/** Used by bt_hci_cmd_send_sync. */
	struct k_sem *sync;
};

#define cmd(buf) ((struct cmd_data *)net_buf_user_data(buf))
#define acl(buf) ((struct acl_data *)net_buf_user_data(buf))

struct bt_dev *bt_dev_get(uint8_t dev_id)
{
	BT_ASSERT_MSG(dev_id < CONFIG_BT_NUM_CTLRS, "Invalid dev_id %u (max %d)",
		 dev_id, CONFIG_BT_NUM_CTLRS);

	return &bt_dev_pool[dev_id];
}

struct bt_dev *bt_dev_alloc(uint8_t dev_id)
{
	struct bt_dev *hdev = NULL;

	if (dev_id >= CONFIG_BT_NUM_CTLRS) {
		return NULL;
	}

	hdev = &bt_dev_pool[dev_id];
	if (hdev->hci) {
		/* Controller already initialized */
		return NULL;
	}

	hdev->dev_id 	   = dev_id;
	k_work_init(&hdev->init, init_work);

#if defined(CONFIG_BT_PRIVACY)
	hdev->rpa_timeout   = CONFIG_BT_RPA_TIMEOUT;
#endif
#if defined(CONFIG_BT_DEVICE_APPEARANCE_DYNAMIC)
	hdev->appearance = CONFIG_BT_DEVICE_APPEARANCE;
#endif
#if DT_HAS_CHOSEN(zephyr_bt_hci)
	if (dev_id == 0) {
		hdev->hci = DEVICE_DT_GET(BT_HCI_DEV(0));
#if defined(CONFIG_BT_MC_DEVICE_INST)
	} else if (dev_id == 1) {
		hdev->hci = DEVICE_DT_GET(BT_HCI_DEV(1));
#endif
	} else {
		hdev->hci = NULL;
		return NULL;
	}
#endif

	return hdev;
}

void bt_dev_free(struct bt_dev *hdev)
{
	ARG_UNUSED(hdev);
	memset(hdev, 0, sizeof(*hdev));
}

