void bt_send_one_host_num_completed_packets(struct bt_dev *hdev, uint16_t handle)
{
	if (!IS_ENABLED(CONFIG_BT_HCI_ACL_FLOW_CONTROL)) {
		ARG_UNUSED(hdev);
		ARG_UNUSED(handle);
		return;
	}

	struct bt_hci_cp_host_num_completed_packets *cp;
	struct bt_hci_handle_count *hc;
	struct net_buf *buf;
	int err;

	LOG_DBG("Reporting completed packet for handle %u", handle);

	buf = bt_hci_cmd_create(BT_HCI_OP_HOST_NUM_COMPLETED_PACKETS,
				sizeof(*cp) + sizeof(*hc));
	BT_ASSERT_MSG(buf, "Unable to alloc for Host NCP");

	cp = net_buf_add(buf, sizeof(*cp));
	cp->num_handles = sys_cpu_to_le16(1);

	hc = net_buf_add(buf, sizeof(*hc));
	hc->handle = sys_cpu_to_le16(handle);
	hc->count  = sys_cpu_to_le16(1);

	err = bt_hci_cmd_send(hdev, BT_HCI_OP_HOST_NUM_COMPLETED_PACKETS, buf);
	BT_ASSERT_MSG(err == 0, "Unable to send Host NCP (err %d)", err);
}

