#if defined(CONFIG_BT_HCI_ACL_FLOW_CONTROL)
void bt_hci_host_num_completed_packets(struct net_buf *buf)
{
	uint16_t handle = acl(buf)->handle;
	struct bt_conn *conn;
	uint8_t index = acl(buf)->index;
	struct bt_dev *hdev = acl(buf)->hdev;

	if (IS_ENABLED(CONFIG_BT_TESTING)) {
		bt_testing_trace_event_acl_pool_destroy(buf);
	}

	net_buf_destroy(buf);

	if (acl(buf)->host_ncp_sent) {
		return;
	}

	/* Do nothing if controller to host flow control is not supported */
	if (!BT_CMD_TEST(hdev->supported_commands, 10, 5)) {
		return;
	}

	conn = bt_conn_lookup_index(hdev, index);
	if (!conn) {
		LOG_WRN("Unable to look up conn with index 0x%02x", index);
		return;
	}

	if (conn->state != BT_CONN_CONNECTED &&
	    conn->state != BT_CONN_DISCONNECTING) {
		LOG_WRN("Not reporting packet for non-connected conn");
		bt_conn_unref(conn);
		return;
	}

	bt_conn_unref(conn);

	bt_send_one_host_num_completed_packets(hdev, handle);
}
#endif /* defined(CONFIG_BT_HCI_ACL_FLOW_CONTROL) */

struct net_buf *bt_hci_cmd_create(uint16_t opcode, uint8_t param_len)
{
	struct bt_hci_cmd_hdr *hdr;
	struct net_buf *buf;

	LOG_DBG("opcode 0x%04x %s param_len %u", opcode, bt_hci_opcode_to_str(opcode), param_len);

	/* net_buf_alloc(K_FOREVER) can fail when run from the syswq */
	buf = net_buf_alloc(&hci_cmd_pool, K_FOREVER);
	if (!buf) {
		LOG_DBG("Unable to allocate a command buffer");
		return NULL;
	}

	LOG_DBG("buf %p", buf);

	net_buf_reserve(buf, BT_BUF_RESERVE);

	bt_buf_set_type(buf, BT_BUF_CMD);

	cmd(buf)->opcode = opcode;
	cmd(buf)->sync = NULL;
	cmd(buf)->state = NULL;

	hdr = net_buf_add(buf, sizeof(*hdr));
	hdr->opcode = sys_cpu_to_le16(opcode);
	hdr->param_len = param_len;

	return buf;
}

int bt_hci_cmd_send(struct bt_dev *hdev, uint16_t opcode, struct net_buf *buf)
{
	if (!buf) {
		buf = bt_hci_cmd_create(opcode, 0);
		if (!buf) {
			return -ENOBUFS;
		}
	}

	LOG_DBG("opcode 0x%04x %s len %u", opcode, bt_hci_opcode_to_str(opcode), buf->len);

	/* Host Number of Completed Packets can ignore the ncmd value
	 * and does not generate any cmd complete/status events.
	 */
	if (opcode == BT_HCI_OP_HOST_NUM_COMPLETED_PACKETS) {
		int err;

		err = bt_send(hdev, buf);
		if (err) {
			LOG_ERR("Unable to send to driver (err %d)", err);
			net_buf_unref(buf);
		}

		return err;
	}

	k_fifo_put(&hdev->cmd_tx_queue, buf);
	bt_tx_irq_raise(hdev);

	return 0;
}

static bool process_pending_cmd(struct bt_dev *hdev, k_timeout_t timeout);
int bt_hci_cmd_send_sync(struct bt_dev *hdev, uint16_t opcode, struct net_buf *buf,
			 struct net_buf **rsp)
{
	struct k_sem sync_sem;
	uint8_t status;
	int err;

	if (!buf) {
		buf = bt_hci_cmd_create(opcode, 0);
		if (!buf) {
			return -ENOBUFS;
		}
	} else {
		/* `cmd(buf)` depends on this  */
		if (net_buf_pool_get(buf->pool_id) != &hci_cmd_pool) {
			__ASSERT_NO_MSG(false);
			return -EINVAL;
		}
	}

	LOG_DBG("buf %p opcode 0x%04x %s len %u", buf, opcode, bt_hci_opcode_to_str(opcode), buf->len);

	/* This local sem is just for suspending the current thread until the
	 * command is processed by the LL. It is given (and we are awaken) by
	 * the cmd_complete/status handlers.
	 */
	k_sem_init(&sync_sem, 0, 1);
	cmd(buf)->sync = &sync_sem;

	k_fifo_put(&hdev->cmd_tx_queue, net_buf_ref(buf));
	bt_tx_irq_raise(hdev);

	/* TODO: disallow sending sync commands from syswq altogether */

	/* Since the commands are now processed in the syswq, we cannot suspend
	 * and wait. We have to send the command from the current context.
	 */
	if (k_current_get() == &k_sys_work_q.thread) {
		/* drain the command queue until we get to send the command of interest. */
		struct net_buf *cmd = NULL;

		do {
			cmd = k_fifo_peek_head(&hdev->cmd_tx_queue);
			LOG_DBG("process cmd %p want %p", cmd, buf);

			/* Wait for a response from the Bluetooth Controller.
			 * The Controller may fail to respond if:
			 *  - It was never programmed or connected.
			 *  - There was a fatal error.
			 *
			 * See the `BT_HCI_OP_` macros in hci_types.h or
			 * Core_v5.4, Vol 4, Part E, Section 5.4.1 and Section 7
			 * to map the opcode to the HCI command documentation.
			 * Example: 0x0c03 represents HCI_Reset command.
			 */
			__maybe_unused bool success = process_pending_cmd(hdev, HCI_CMD_TIMEOUT);

			BT_ASSERT_MSG(success, "command opcode 0x%04x %s timeout", opcode, bt_hci_opcode_to_str(opcode));
		} while (buf != cmd);
	}

	/* Now that we have sent the command, suspend until the LL replies */
	err = k_sem_take(&sync_sem, HCI_CMD_TIMEOUT);
	BT_ASSERT_MSG(err == 0,
		      "Controller unresponsive, command opcode 0x%04x %s timeout with err %d",
		      opcode, bt_hci_opcode_to_str(opcode), err);

	status = cmd(buf)->status;
	if (status) {
		LOG_WRN("opcode 0x%04x %s status 0x%02x %s", opcode, bt_hci_opcode_to_str(opcode),
			status, bt_hci_err_to_str(status));
		net_buf_unref(buf);

		switch (status) {
		case BT_HCI_ERR_CONN_LIMIT_EXCEEDED:
			return -ECONNREFUSED;
		case BT_HCI_ERR_INSUFFICIENT_RESOURCES:
			return -ENOMEM;
		case BT_HCI_ERR_INVALID_PARAM:
			return -EINVAL;
		case BT_HCI_ERR_CMD_DISALLOWED:
			return -EACCES;
		default:
			return -EIO;
		}
	}

	LOG_DBG("rsp %p opcode 0x%04x %s len %u", buf, opcode, bt_hci_opcode_to_str(opcode), buf->len);

	if (rsp) {
		*rsp = buf;
	} else {
		net_buf_unref(buf);
	}

	return 0;
}

