static void hci_reset_complete(struct bt_dev *hdev)
{
	atomic_t flags;

	if (IS_ENABLED(CONFIG_BT_OBSERVER)) {
		bt_scan_reset(hdev);
	}

#if defined(CONFIG_BT_CLASSIC)
	bt_br_discovery_reset(hdev);
#endif /* CONFIG_BT_CLASSIC */

	flags = (atomic_get(hdev->flags) & BT_DEV_PERSISTENT_FLAGS);
	atomic_set(hdev->flags, flags);
}

static void hci_cmd_done(struct bt_dev *hdev, uint16_t opcode,
			 uint8_t status, struct net_buf *evt_buf)
{
	/* Original command buffer. */
	struct net_buf *buf = NULL;

	LOG_DBG("opcode 0x%04x %s, status 0x%02x %s buf %p", opcode,
		bt_hci_opcode_to_str(opcode),
		status, bt_hci_err_to_str(status), evt_buf);

	/* Unsolicited cmd complete. This does not complete a command.
	 * The controller can send these for effect of the `ncmd` field.
	 */
	if (opcode == 0) {
		goto exit;
	}

	/* Take the original command buffer reference. */
	buf = (struct net_buf *)atomic_ptr_clear((atomic_ptr_t *)&hdev->sent_cmd);

	if (!buf) {
		LOG_ERR("No command sent for cmd complete 0x%04x", opcode);
		goto exit;
	}

	if (cmd(buf)->opcode != opcode) {
		LOG_ERR("OpCode 0x%04x %s completed instead of expected 0x%04x %s", opcode,
			bt_hci_opcode_to_str(opcode), cmd(buf)->opcode, bt_hci_opcode_to_str(cmd(buf)->opcode));
		buf = atomic_ptr_set((atomic_ptr_t *)&hdev->sent_cmd, buf);
		__ASSERT_NO_MSG(!buf);
		goto exit;
	}

	/* Response data is to be delivered in the original command
	 * buffer.
	 */
	if (evt_buf != buf) {
		net_buf_reset(buf);
		bt_buf_set_type(buf, BT_BUF_EVT);
		net_buf_reserve(buf, BT_BUF_RESERVE);
		net_buf_add_mem(buf, evt_buf->data, evt_buf->len);
	}

	if (cmd(buf)->state && !status) {
		struct bt_hci_cmd_state_set *update = cmd(buf)->state;

		atomic_set_bit_to(update->target, update->bit, update->val);
	}

	/* If the command was synchronous wake up bt_hci_cmd_send_sync() */
	if (cmd(buf)->sync) {
		LOG_DBG("sync cmd released");
		cmd(buf)->status = status;
		k_sem_give(cmd(buf)->sync);
	}

exit:
	if (buf) {
		net_buf_unref(buf);
	}
}

static void hci_cmd_complete(struct bt_dev *hdev, struct net_buf *buf)
{
	struct bt_hci_evt_cmd_complete *evt;
	uint8_t status, ncmd;
	uint16_t opcode;

	evt = net_buf_pull_mem(buf, sizeof(*evt));
	ncmd = evt->ncmd;
	opcode = sys_le16_to_cpu(evt->opcode);

	LOG_DBG("opcode 0x%04x %s", opcode, bt_hci_opcode_to_str(opcode));

	/* All command return parameters have a 1-byte status in the
	 * beginning, so we can safely make this generalization.
	 */
	status = buf->data[0];

	/* HOST_NUM_COMPLETED_PACKETS should not generate a response under normal operation.
	 * The generation of this command ignores `ncmd_sem`, so should not be given here.
	 */
	if (opcode == BT_HCI_OP_HOST_NUM_COMPLETED_PACKETS) {
		LOG_WRN("Unexpected HOST_NUM_COMPLETED_PACKETS, status 0x%02x %s",
			status, bt_hci_err_to_str(status));
		return;
	}

	hci_cmd_done(hdev, opcode, status, buf);

	/* Allow next command to be sent */
	if (ncmd) {
		k_sem_give(&hdev->ncmd_sem);
		bt_tx_irq_raise(hdev);
	}

