#if defined(CONFIG_BT_SMP)
static void le_ltk_neg_reply(struct bt_dev *hdev, uint16_t handle)
{
	struct bt_hci_cp_le_ltk_req_neg_reply *cp;
	struct net_buf *buf;

	buf = bt_hci_cmd_create(BT_HCI_OP_LE_LTK_REQ_NEG_REPLY, sizeof(*cp));
	if (!buf) {
		LOG_ERR("Out of command buffers");

		return;
	}

	cp = net_buf_add(buf, sizeof(*cp));
	cp->handle = sys_cpu_to_le16(handle);

	bt_hci_cmd_send(hdev, BT_HCI_OP_LE_LTK_REQ_NEG_REPLY, buf);
}

static void le_ltk_reply(struct bt_dev *hdev, uint16_t handle, uint8_t *ltk)
{
	struct bt_hci_cp_le_ltk_req_reply *cp;
	struct net_buf *buf;

	buf = bt_hci_cmd_create(BT_HCI_OP_LE_LTK_REQ_REPLY,
				sizeof(*cp));
	if (!buf) {
		LOG_ERR("Out of command buffers");
		return;
	}

	cp = net_buf_add(buf, sizeof(*cp));
	cp->handle = sys_cpu_to_le16(handle);
	memcpy(cp->ltk, ltk, sizeof(cp->ltk));

	LOG_DBG("----------- le ltk:%s. ------------", bt_hex(cp->ltk, sizeof(cp->ltk)));

	bt_hci_cmd_send(hdev, BT_HCI_OP_LE_LTK_REQ_REPLY, buf);
}

static void le_ltk_request(struct bt_dev *hdev, struct net_buf *buf)
{
	struct bt_hci_evt_le_ltk_request *evt = (void *)buf->data;

 *
 * @param evt HCI event code.
 *
 * @return HCI event flags for the specified event.
 */
static inline uint8_t bt_hci_evt_get_flags(uint8_t evt)
{
	switch (evt) {
	case BT_HCI_EVT_DISCONN_COMPLETE:
		return BT_HCI_EVT_FLAG_RECV | BT_HCI_EVT_FLAG_RECV_PRIO;
		/* fallthrough */
#if defined(CONFIG_BT_CONN) || defined(CONFIG_BT_ISO)
	case BT_HCI_EVT_NUM_COMPLETED_PACKETS:
#if defined(CONFIG_BT_CONN)
	case BT_HCI_EVT_DATA_BUF_OVERFLOW:
		__fallthrough;
#endif /* defined(CONFIG_BT_CONN) */
#endif /* CONFIG_BT_CONN ||  CONFIG_BT_ISO */
	case BT_HCI_EVT_CMD_COMPLETE:
	case BT_HCI_EVT_CMD_STATUS:
		return BT_HCI_EVT_FLAG_RECV_PRIO;
	default:
		return BT_HCI_EVT_FLAG_RECV;
	}
}

static void hci_event(struct bt_dev *hdev, struct net_buf *buf)
{
	struct bt_hci_evt_hdr *hdr;

	if (buf->len < sizeof(*hdr)) {
		LOG_ERR("Invalid HCI event size (%u)", buf->len);
		net_buf_unref(buf);
		return;
	}

	hdr = net_buf_pull_mem(buf, sizeof(*hdr));
	LOG_DBG("event 0x%02x", hdr->evt);
	BT_ASSERT(bt_hci_evt_get_flags(hdr->evt) & BT_HCI_EVT_FLAG_RECV);

	handle_event(hdev, hdr->evt, buf, normal_events, ARRAY_SIZE(normal_events));

	net_buf_unref(buf);
}

static void hci_core_send_cmd(struct bt_dev *hdev)
{
	struct net_buf *buf;
	int err;

	/* Get next command */
	LOG_DBG("dev:%d, fetch cmd", hdev->dev_id);
	buf = k_fifo_get(&hdev->cmd_tx_queue, K_NO_WAIT);
	BT_ASSERT(buf);

	/* Clear out any existing sent command */
	if (hdev->sent_cmd) {
		LOG_ERR("Uncleared pending sent_cmd");
		net_buf_unref(hdev->sent_cmd);
		hdev->sent_cmd = NULL;
	}

	hdev->sent_cmd = net_buf_ref(buf);

	LOG_DBG("Sending command 0x%04x %s (buf %p) to driver", cmd(buf)->opcode, bt_hci_opcode_to_str(cmd(buf)->opcode), buf);

	err = bt_send(hdev, buf);
	if (err) {
		LOG_ERR("Unable to send to driver (err %d)", err);
		k_sem_give(&hdev->ncmd_sem);
		hci_cmd_done(hdev, cmd(buf)->opcode, BT_HCI_ERR_UNSPECIFIED, buf);
		net_buf_unref(buf);
		bt_tx_irq_raise(hdev);
	}
}

