553	static int32_t sf32lb52_bt_rx_ind(ipc_queue_handle_t handle, size_t size)
554	{
555	  struct sf32lb52_bt_env_s *env = &g_sf32lb52_bt_env;
556	  irqstate_t flags;
557	  bool queue_work;
558	
559	  syslog(LOG_ERR, "[BTDBG] RX ind handle=%d size=%lu open=%d\\n",
560	         handle, (unsigned long)size, env->queue_open ? 1 : 0);
561	
562	  if (handle != env->ipc_port)
563	    {
564	      return -EINVAL;
565	    }
566	
567	  if (!env->queue_open)
568	    {
569	      struct circular_buf *rx_ring = (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
570	      #if SF32LB52_BT_TRACE
571	            syslog(LOG_INFO, "sf32lb52 rx_ind (pre-open) wr=%08lx rd=%08lx\n",
572	              (unsigned long)rx_ring->write_idx_mirror,
573	              (unsigned long)rx_ring->read_idx_mirror);
574	      #endif
575	      return OK;
576	    }
577	
578	  flags = enter_critical_section();
579	  env->rx_work_pending = true;
580	  queue_work = !env->rx_worker_running && work_available(&env->rx_work);
581	  if (queue_work)
582	    {
583	      env->rx_worker_running = true;
584	    }
585	  leave_critical_section(flags);
586	
587	#if SF32LB52_BT_TRACE
588	  {
589	    struct circular_buf *rx_ring =
590	        (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
591	
592	    up_invalidate_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
593	                         (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
594	                         sizeof(*rx_ring));
595	
596	    syslog(LOG_INFO,
597	           "sf32lb52 rx_ind: size=%lu local=%08lx rd=%08lx wr=%08lx\n",
598	           (unsigned long)size,
599	           (unsigned long)env->rx_read_idx_mirror,
600	           (unsigned long)rx_ring->read_idx_mirror,
601	           (unsigned long)rx_ring->write_idx_mirror);
602	  }
603	#endif
604	
605	  if (queue_work)
606	    {
607	      int ret;
608	
609	      ret = work_queue(HPWORK, &env->rx_work, sf32lb52_bt_rx_worker,
610	                       env, 0);
611	      if (ret < 0)
612	        {
613	          flags = enter_critical_section();
614	          env->rx_worker_running = false;
615	          leave_critical_section(flags);
616	
617	          syslog(LOG_ERR, "sf32lb52 bt queue rx work failed: %d\n", ret);
618	          return ret;
619	        }
620	    }
621	
622	  return OK;
623	}
