725	int sf32lb52_bt_controller_enable(void)
726	{
727	  int ret;
728	
729	  syslog(LOG_ERR, "[BTDBG] controller_enable status=%d\\n",
730	         (int)g_sf32lb52_bt_status);
731	
732	  if (g_sf32lb52_bt_status == SF32LB52_BT_STATUS_ENABLED)
733	    {
734	      return OK;
735	    }
736	
737	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_INITED)
738	    {
739	      return -EPERM;
740	    }
741	
742	  sf32lb52_bt_prepare_stack_nvds();
743	  HAL_LCPU_ASSERT_INFO_clear();
744	
745	  ret = lcpu_power_on();
746	  if (ret != 0)
747	    {
748	      return -EIO;
749	    }
750	
751	  /* The L2H_MAILBOX (0x40002000) is on the LPSYS APB bus.  Its CxIER
752	   * register is only writable when the LPSYS bus bridge is active.
753	   * Wake the LCPU first so the bus bridge is powered, THEN open the
754	   * IPC queue (which writes CxIER to unmask the mailbox RX interrupt).
755	   * The SDK reference ipc_hw_enable_interrupt2() has the same
756	   * HAL_HPAON_WakeCore() before the UNMASK call.
757	   */
758	
759	  HAL_HPAON_WakeCore(CORE_ID_LCPU);
760	  g_sf32lb52_bt_env.wake_held = true;
761	
762	  usleep(500000);
763	
764	  ret = ipc_queue_open(g_sf32lb52_bt_env.ipc_port);
765	  if (ret < 0)
766	    {
767	      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
768	      g_sf32lb52_bt_env.wake_held = false;
769	      return ret;
770	    }
771	
772	  /* Flush H2L TX ring to SRAM immediately after ipc_queue_open so
773	   * LCPU sees the reset indices (read_idx=write_idx=0) before it
774	   * tries to process any stale data from a previous session.
775	   */
776	  up_clean_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
777	                  (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
778	                  SF32LB52_BT_TX_BUF_SIZE);
779	  __DSB();
780	
781	  /* After every lcpu_power_on(), LCPU resets its TX ring write pointer
782	   * (write_idx_mirror) to 0 and writes its own boot responses into the
783	   * ring.  HCPU's read pointer (read_idx_mirror) may still hold the
784	   * non-zero value from the previous session -- dirty in DCache or
785	   * stored in SRAM.  If we do not synchronise them:
786	   *
787	   *   circular_buf_data_len() = wrap(write_idx - read_idx)
788	   *
789	   * returns a large garbage value, and LCPU's fresh boot events
790	   * plus ring garbage all replay as "new" HCI responses.  These
791	   * ghost events are consumed by the host as replies to real commands,
792	   * so HCI_Reset (0x0c01) is never actually executed by the controller,
793	   * and bt_le_adv_start later gets "Command Disallowed" (0x07).
794	   *
795	   * Fix: flush DCache to write back any dirty read_idx and to load
796	   * LCPU's current write_idx from SRAM, then advance read_idx to
797	   * write_idx (discard ALL pending LCPU boot data), then clean the
798	   * DCache so LCPU sees the updated read pointer in SRAM.
799	   */
800	
801	  {
802	    struct circular_buf *rx_ring =
803	        (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
804	
805	    ret = sf32lb52_bt_wait_rx_ring_ready();
806	    if (ret < 0)
807	      {
808	        syslog(LOG_ERR, "sf32lb52 rx ring not ready: %d\n", ret);
809	        ipc_queue_close(g_sf32lb52_bt_env.ipc_port);
810	        HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
811	        g_sf32lb52_bt_env.wake_held = false;
812	        return ret;
813	      }
814	
815	    rx_ring->read_idx_mirror = rx_ring->write_idx_mirror;
816	    g_sf32lb52_bt_env.rx_read_idx_mirror = rx_ring->write_idx_mirror;
817	
818	    up_clean_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
819	                    (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
820	                    sizeof(*rx_ring));
821	    __DSB();
822	  }
823	
824	  {
825	    volatile MAILBOX_CH_TypeDef *l2h = L2H_MAILBOX;
826	    uint32_t nvic_bit = (1UL << (LCPU2HCPU_IRQn & 0x1F));
827	    uint32_t nvic_en  = NVIC->ISER[LCPU2HCPU_IRQn >> 5];
828	
829	    (void)l2h;
830	    (void)nvic_bit;
831	    (void)nvic_en;
832	  }
833	
834	  g_sf32lb52_bt_env.queue_open = true;
835	  g_sf32lb52_bt_status = SF32LB52_BT_STATUS_ENABLED;
836	
837	  return OK;
838	}
