840	int sf32lb52_bt_controller_disable(void)
841	{
842	  int ret = OK;
843	  int tmpret;
844	  bool queue_open;
845	
846	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_ENABLED)
847	    {
848	      return -EPERM;
849	    }
850	
851	  queue_open = g_sf32lb52_bt_env.queue_open;
852	  g_sf32lb52_bt_env.queue_open = false;
853	  g_sf32lb52_bt_env.rx_work_pending = false;
854	  g_sf32lb52_bt_env.rx_worker_running = false;
855	  if (!work_available(&g_sf32lb52_bt_env.rx_work))
856	    {
857	      tmpret = work_cancel_sync(HPWORK, &g_sf32lb52_bt_env.rx_work);
858	      if (tmpret < 0 && tmpret != -ENOENT && ret == OK)
859	        {
860	          ret = tmpret;
861	        }
862	    }
863	
864	  if (queue_open)
865	    {
866	      tmpret = ipc_queue_close(g_sf32lb52_bt_env.ipc_port);
867	      if (tmpret < 0 && ret == OK)
868	        {
869	          ret = tmpret;
870	        }
871	    }
872	
873	  if (g_sf32lb52_bt_env.wake_held)
874	    {
875	      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
876	      g_sf32lb52_bt_env.wake_held = false;
877	    }
878	
879	  tmpret = lcpu_power_off();
880	  if (tmpret != 0 && ret == OK)
881	    {
882	      ret = -EIO;
883	    }
884	
885	  g_sf32lb52_bt_env.notify_host = NULL;
886	  g_sf32lb52_bt_status = SF32LB52_BT_STATUS_INITED;
887	  return ret;
888	}
