890	int sf32lb52_host_send_packet(const uint8_t *data, uint16_t len)
891	{
892	  struct circular_buf *tx_ring =
893	      (struct circular_buf *)SF32LB52_BT_TX_BUF_ADDR;
894	  uint32_t start_time;
895	  uint32_t tick_count;
896	  size_t written;
897	  size_t remaining;
898	  size_t offset;
899	  size_t chunk;
900	  size_t chunks;
901	  uint32_t wr_ptr;
902	  int ret;
903	
904	  syslog(LOG_ERR, "[BTDBG] host_send_packet len=%u status=%d open=%d\\n",
905	         len, (int)g_sf32lb52_bt_status,
906	         g_sf32lb52_bt_env.queue_open ? 1 : 0);
907	
908	  if (data == NULL || len == 0)
909	    {
910	      return -EINVAL;
911	    }
912	
913	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_ENABLED ||
914	      !g_sf32lb52_bt_env.queue_open)
915	    {
916	      return -ENODEV;
917	    }
918	
919	  offset = 0;
920	  remaining = len;
921	  start_time = HAL_GetTick();
922	  tick_count = 0;
923	  chunks = 0;
924	  wr_ptr = 0;
925	
926	  ret = sf32lb52_bt_wait_tx_idle(tx_ring);
927	  if (ret < 0)
928	    {
929	      return ret;
930	    }
931	
932	  while (remaining > 0)
933	    {
934	      irqstate_t flags;
935	
936	      chunk = sf32lb52_bt_tx_chunk_len(data, len, offset);
937	
938	      up_invalidate_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
939	                           (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
940	                           sizeof(*tx_ring));
941	
942	      flags = enter_critical_section();
943	      written = sf32lb52_bt_ring_write(tx_ring, data + offset, chunk);
944	      leave_critical_section(flags);
945	
946	      if (written == 0)
947	        {
948	          if (HAL_GetTick() != start_time)
949	            {
950	              tick_count++;
951	              start_time = HAL_GetTick();
952	            }
953	
954	          if (tick_count >= 10)
955	            {
956	              syslog(LOG_ERR,
957	                     "sf32lb52 bt tx timeout: remaining=%lu\n",
958	                     (unsigned long)remaining);
959	              return -ETIMEDOUT;
960	            }
961	
962	          continue;
963	        }
964	
965	      offset += written;
966	      remaining -= written;
967	
968	      __DSB();
969	      wr_ptr = tx_ring->write_idx_mirror;
970	      sf32lb52_bt_trigger_tx();
971	      chunks++;
972	    }
973	
974	#if SF32LB52_BT_TRACE
975	  syslog(LOG_INFO,
976	         "sf32lb52 bt tx publish: total=%u chunks=%lu wr=%08lx first=%02x\n",
977	         len,
978	         (unsigned long)chunks,
979	         (unsigned long)wr_ptr,
980	         data[0]);
981	
982	  sf32lb52_bt_log_tx_state(tx_ring, "queued", wr_ptr);
983	#endif
984	
985	  if (data[0] == SF32LB52_BT_H4_CMD)
986	    {
987	      ret = sf32lb52_bt_wait_tx_idle(tx_ring);
988	      if (ret < 0)
989	        {
990	          return ret;
991	        }
992	    }
993	
994	  return OK;
995	}
450	      case BT_HCI_OP_SET_CTL_TO_HOST_FLOW:
451	        *ret = sf32lb52_bt_synth_status_complete(priv, opcode);
452	        return true;
453	
454	      default:
455	        return false;
456	    }
457	}
