470	static int sf32lb52_bt_recv_cb(uint8_t *data, uint16_t len)
471	{
472	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
473	  ssize_t packet_len;
474	  int ret;
475	
476	  if (data == NULL || len == 0)
477	    {
478	      return -EINVAL;
479	    }
480	
481	  syslog(LOG_ERR, "[BTDBG] HCI RX callback len=%u first=%02x drop=%d\\n",
482	         len, data[0], priv->drop_rx_until_tx ? 1 : 0);
483	
484	  if (priv->drop_rx_until_tx)
485	    {
486	      return OK;
487	    }
488	
489	  if (priv->rxlen + len > sizeof(priv->rxbuf))
490	    {
491	      syslog(LOG_ERR,
492	             "sf32lb52 bth4 rx overflow: pending=%lu incoming=%u\n",
493	             (unsigned long)priv->rxlen,
494	             len);
495	      priv->rxlen = 0;
496	    }
497	
498	  memcpy(&priv->rxbuf[priv->rxlen], data, len);
499	  priv->rxlen += len;
500	
501	#if SF32LB52_BT_TRACE
502	  syslog(LOG_INFO,
503	         "sf32lb52 bth4 recv: len=%u pending=%lu first=%02x\n",
504	         len, (unsigned long)priv->rxlen, priv->rxbuf[0]);
505	#endif
506	
507	  ret = OK;
508	
509	  while (priv->rxlen > 0)
510	    {
511	      packet_len = sf32lb52_bt_h4_packet_len(priv->rxbuf, priv->rxlen);
512	      if (packet_len == 0)
513	        {
514	          break;
515	        }
516	
517	      if (packet_len < 0)
518	        {
519	          syslog(LOG_WARNING,
520	                 "sf32lb52 bth4 drop invalid h4 type=%02x pending=%lu\n",
521	                 priv->rxbuf[0],
522	                 (unsigned long)priv->rxlen);
523	          memmove(priv->rxbuf, &priv->rxbuf[1], priv->rxlen - 1);
524	          priv->rxlen--;
525	          ret = -EINVAL;
526	          continue;
527	        }
528	
529	      if ((size_t)packet_len > priv->rxlen)
530	        {
531	          break;
532	        }
533	
534	      ret = sf32lb52_bt_forward_packet(priv, priv->rxbuf,
535	                   (size_t)packet_len);
536	
537	      priv->rxlen -= (size_t)packet_len;
538	      if (priv->rxlen > 0)
539	        {
540	          memmove(priv->rxbuf,
541	                  &priv->rxbuf[packet_len],
542	                  priv->rxlen);
543	        }
544	    }
545	
546	  return ret;
547	}
548	
549	static int sf32lb52_bt_send(struct bt_driver_s *drv,
550	                            enum bt_buf_type_e type,
551	                            void *data, size_t len)
552	{
553	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
554	  uint8_t *hdr = (uint8_t *)data - drv->head_reserve;
555	  uint16_t opcode;
556	  int ret;
557	
558	  syslog(LOG_ERR, "[BTDBG] HCI TX type=%u len=%lu\\n",
559	         (unsigned int)type, (unsigned long)len);
560	
561	  switch (type)
562	    {
563	      case BT_CMD:
564	        *hdr = H4_CMD;
565	        break;
566	      case BT_ACL_OUT:
567	        *hdr = H4_ACL;
568	        break;
569	      case BT_ISO_OUT:
570	        *hdr = H4_ISO;
571	        break;
572	      default:
573	        return -EINVAL;
574	    }
575	
576	  if (type == BT_CMD && len >= sizeof(struct bt_hci_cmd_hdr_s))
577	    {
578	      opcode = sf32lb52_bt_get_le16(data);
579	      if (sf32lb52_bt_emulate_cmd(priv, opcode, &ret))
580	        {
581	          return ret < 0 ? ret : len;
582	        }
583	
584	      ret = sf32lb52_bt_ensure_controller_enabled(opcode);
585	      if (ret < 0)
586	        {
587	          syslog(LOG_ERR, "[BTDBG] enable opcode=0x%04x ret=%d\\n",
588	                 opcode, ret);
589	          return ret;
590	        }
591	    }
592	  else
593	    {
594	      ret = sf32lb52_bt_ensure_controller_enabled(0);
595	      if (ret < 0)
596	        {
597	          return ret;
598	        }
599	    }
600	
601	  priv->drop_rx_until_tx = false;
602	
603	  if (SF32LB52_BT_TRACE && type == BT_ACL_OUT)
604	    {
605	      syslog(LOG_INFO,
606	             "sf32lb52 bth4 tx: type=%u len=%lu h4=%02x acl=%02x %02x %02x %02x\n",
607	             (unsigned int)type,
608	             (unsigned long)(len + drv->head_reserve),
609	             hdr[0],
610	             len >= 1 ? hdr[1] : 0,
611	             len >= 2 ? hdr[2] : 0,
612	             len >= 3 ? hdr[3] : 0,
613	             len >= 4 ? hdr[4] : 0);
614	    }
615	
616	  ret = sf32lb52_host_send_packet(hdr, len + drv->head_reserve);
617	  syslog(LOG_ERR, "[BTDBG] host_send ret=%d\\n", ret);
618	  if (ret < 0)
619	    {
620	      return ret;
621	    }
622	
623	  return len;
624	}
