626	static int sf32lb52_bt_ensure_controller_enabled(uint16_t opcode)
627	{
628	  int ret;
629	
630	  ret = sf32lb52_bt_controller_enable();
631	  if (ret < 0)
632	    {
633	      syslog(LOG_ERR,
634	             "sf32lb52 bth4 controller enable failed before opcode=0x%04x: %d\n",
635	             opcode,
636	             ret);
637	    }
638	
639	  return ret;
640	}
