642	static int sf32lb52_bt_open(struct bt_driver_s *drv)
643	{
644	  int ret;
645	
646	  (void)drv;
647	
648	  g_sf32lb52_bt_priv.rxlen = 0;
649	  g_sf32lb52_bt_priv.drop_rx_until_tx = true;
650	
651	  ret = sf32lb52_bt_controller_init();
652	  if (ret < 0)
653	    {
654	      return ret;
655	    }
