   540	int bt_hci_le_rand_mc(uint8_t dev_id, void *buffer, size_t len)
   541	{
   542		struct bt_hci_rp_le_rand *rp;
   543		struct net_buf *rsp;
   544		size_t count;
   545		int err;
   546		struct bt_dev *hdev;
   547	
   548		hdev = bt_dev_get(dev_id);
   549		if (!hdev) {
   550			return -ENODEV;
   551		}
   552	
   553		/* Check first that HCI_LE_Rand is supported */
   554		if (!BT_CMD_TEST(hdev->supported_commands, 27, 7)) {
   555			return -ENOTSUP;
   556		}
   557	
   558		while (len > 0) {
   559			/* Number of bytes to fill on this iteration */
   560			count = MIN(len, sizeof(rp->rand));
   561			/* Request the next 8 bytes over HCI */
   562			err = bt_hci_cmd_send_sync(hdev, BT_HCI_OP_LE_RAND, NULL, &rsp);
   563			if (err) {
   564				return err;
   565			}
   566			/* Copy random data into buffer */
   567			rp = (void *)rsp->data;
   568			memcpy(buffer, rp->rand, count);
   569	
   570			net_buf_unref(rsp);
   571			buffer = (uint8_t *)buffer + count;
   572			len -= count;
   573		}
   574	
   575		return 0;
   576	}
