    return False


def strip_ansi(text: str) -> str:
    return ANSI_ESCAPE.sub("", text)


def canonical_interface(name: str | None) -> str | None:
    if not name:
        return None
    lowered = name.lower()
    if lowered == "daplink":
        return "cmsis-dap"
    return lowered


def detect_device_label(description: str) -> str:
    desc = description.upper()
    if "CH340" in desc or "CH341" in desc:
        return "USB 转串口"
    if "CMSIS-DAP" in desc or "DAPLINK" in desc or "DAP-LINK" in desc:
        return "CMSIS-DAP"
    if "STLINK" in desc or "ST-LINK" in desc:
        return "ST-Link"
    if "J-LINK" in desc or "JLINK" in desc:
        return "J-Link"
    if "CP210" in desc:
        return "CP210x"
    if "USB SERIAL" in desc or "USB-SERIAL" in desc:
        return "USB 串口"
    return ""


def port_priority(description: str) -> int:
    desc = description.upper()
    if "CH340" in desc or "CH341" in desc or "CP210" in desc:
        return 1
    if "CMSIS-DAP" in desc or "DAPLINK" in desc or "STLINK" in desc or "J-LINK" in desc:
        return 2
    if "USB" in desc:
        return 3
    return 9


def list_serial_ports() -> list[str]:
    if not require_pyserial():
        return []

    ports = list(list_ports.comports())
    if not ports:
        print("❌ 未找到可用串口")
        return []

    print("📡 可用串口：")
    devices: list[str] = []
    for index, port in enumerate(ports, start=1):
        label = detect_device_label(port.description)
        extra = f" [{label}]" if label else ""
        print(f"  {index}. {port.device}: {port.description}{extra}")
        devices.append(port.device)
    return devices


def auto_detect_port() -> str | None:
    if not require_pyserial():
        return None

    candidates = [
        (port_priority(port.description), port.device)
        for port in list_ports.comports()
    ]
    if not candidates:
        return None

    candidates.sort(key=lambda item: (item[0], item[1]))
    return candidates[0][1]


def open_serial(port: str, baudrate: int):
    if not require_pyserial():
        return None

    try:
        serial_handle = pyserial.Serial(
            port=port,
            baudrate=baudrate,
            timeout=0.1,
            bytesize=pyserial.EIGHTBITS,
            parity=pyserial.PARITY_NONE,
            stopbits=pyserial.STOPBITS_ONE,
        )
        time.sleep(0.1)
        return serial_handle
    except pyserial.SerialException as exc:
        print(f"❌ 无法打开串口 {port}: {exc}")
        return None


def _read_openocd_path() -> str | None:
    """从工作区 .em_skill.json 读取已配置的 openocd 路径，否则走 PATH。"""
    ws = Path.cwd()
    for _ in range(5):
        cfg = ws / ".em_skill.json"
        if cfg.is_file():
            try:
                data = json.loads(cfg.read_text(encoding="utf-8"))
                p = data.get("tools", {}).get("openocd")
                if p:
                    return p
            except Exception:
                pass
        ws = ws.parent
    return None


def _find_openocd() -> str | None:
    """返回 openocd 可执行文件路径，优先用配置文件。"""
    cfg_path = _read_openocd_path()
    if cfg_path and Path(cfg_path).is_file():
        return cfg_path
    return shutil.which("openocd")


def check_openocd() -> bool:
